import{_ as t,c as a,o as s,a2 as o}from"./chunks/framework.PGES7OoM.js";const c=JSON.parse('{"title":"Make Your Existing Assets Private","description":"","frontmatter":{"rawMarkdown":"# Make Your Existing Assets Private\\n\\nTo use Curvy for private payments, you first need to get some assets into your Curvy App.\\n\\nThis process is commonly referred to as \\"shielding\\", as Curvy shields your funds from prying eyes.\\n\\n## From the Curvy app\\n\\nThe easiest way to shield funds is to deposit them from a wallet you already own:\\n\\n1. Open **Receive** in the Curvy App and find the **Add from your wallet** section.\\n2. Choose **Connect wallet** and pick an Ethereum / EVM wallet or a Solana wallet.\\n3. Curvy lists the balances in that wallet that it can deposit. Pick one and enter the amount.\\n4. Choose **Review deposit**, check the details, and confirm in your wallet.\\n\\nYou can follow the deposit as it settles. The funds show up in your private balance once they are confirmed.\\n\\n## From an ENS compatible wallet\\n\\nIf you are using a wallet that supports Ethereum Name Service, such as MetaMask or Rabby,\\nyou can just enter your Curvy ID (for example `your-curvy-id.curvy.name`) as the recipient for a new transaction.\\nThe wallet resolves it to a fresh private address for you.\\n\\n## Receiving from other wallets\\n\\nTo receive funds from other wallets, you can simply instruct the sender to open your receiving page:\\n\\n```\\nhttps://your-curvy-id.curvy.name\\n```\\n\\nThe page lets them choose EVM or Solana and then **Get payment address**, which creates a one-time private receiving address to which they can send the funds on any [supported network](/for-users/#supported-networks-and-tokens) of that kind.\\nEach address should be used once: only the first transfer to it is forwarded automatically.\\n\\nYou can copy or show a QR code of this link from the **Receive** page of the Curvy App.\\n","rawMarkdownPath":"/_raw/for-users/make-your-existing-assets-private.md","rawMarkdownTitle":"Make Your Existing Assets Private","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/make-your-existing-assets-private.md"},"headers":[],"relativePath":"for-users/make-your-existing-assets-private.md","filePath":"for-users/make-your-existing-assets-private.md","lastUpdated":1791449043000}'),r={name:"for-users/make-your-existing-assets-private.md"};function n(i,e,l,u,h,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="make-your-existing-assets-private" tabindex="-1">Make Your Existing Assets Private <a class="header-anchor" href="#make-your-existing-assets-private" aria-label="Permalink to &quot;Make Your Existing Assets Private&quot;">​</a></h1><p>To use Curvy for private payments, you first need to get some assets into your Curvy App.</p><p>This process is commonly referred to as &quot;shielding&quot;, as Curvy shields your funds from prying eyes.</p><h2 id="from-the-curvy-app" tabindex="-1">From the Curvy app <a class="header-anchor" href="#from-the-curvy-app" aria-label="Permalink to &quot;From the Curvy app&quot;">​</a></h2><p>The easiest way to shield funds is to deposit them from a wallet you already own:</p><ol><li>Open <strong>Receive</strong> in the Curvy App and find the <strong>Add from your wallet</strong> section.</li><li>Choose <strong>Connect wallet</strong> and pick an Ethereum / EVM wallet or a Solana wallet.</li><li>Curvy lists the balances in that wallet that it can deposit. Pick one and enter the amount.</li><li>Choose <strong>Review deposit</strong>, check the details, and confirm in your wallet.</li></ol><p>You can follow the deposit as it settles. The funds show up in your private balance once they are confirmed.</p><h2 id="from-an-ens-compatible-wallet" tabindex="-1">From an ENS compatible wallet <a class="header-anchor" href="#from-an-ens-compatible-wallet" aria-label="Permalink to &quot;From an ENS compatible wallet&quot;">​</a></h2><p>If you are using a wallet that supports Ethereum Name Service, such as MetaMask or Rabby, you can just enter your Curvy ID (for example <code>your-curvy-id.curvy.name</code>) as the recipient for a new transaction. The wallet resolves it to a fresh private address for you.</p><h2 id="receiving-from-other-wallets" tabindex="-1">Receiving from other wallets <a class="header-anchor" href="#receiving-from-other-wallets" aria-label="Permalink to &quot;Receiving from other wallets&quot;">​</a></h2><p>To receive funds from other wallets, you can simply instruct the sender to open your receiving page:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-curvy-id.curvy.name</span></span></code></pre></div><p>The page lets them choose EVM or Solana and then <strong>Get payment address</strong>, which creates a one-time private receiving address to which they can send the funds on any <a href="/for-users/#supported-networks-and-tokens">supported network</a> of that kind. Each address should be used once: only the first transfer to it is forwarded automatically.</p><p>You can copy or show a QR code of this link from the <strong>Receive</strong> page of the Curvy App.</p>',14)])])}const y=t(r,[["render",n]]);export{c as __pageData,y as default};
